		// @01b2a610
		private static string GetStringFromTable(string[] table, int index) {
			if (index >= 0 && index < table.Length)
				return table[index];
			return string.Format("out of range.[{0}]", index);
		}
		// @01b2aa90: Array.IndexOf clamped at 0 (`bic w0, w0, w0, asr #31`)
		private static int GetIndexFromTable(string[] table, string s) {
			int index = System.Array.IndexOf(table, s);
			return index < 0 ? 0 : index;
		}
